  2296  /* ----------------------------------------------------------------------
  2297   * Reference sequence handling
  2298   *
  2299   * These revolve around the refs_t structure, which may potentially be
  2300   * shared between multiple cram_fd.
  2301   *
  2302   * We start with refs_create() to allocate an empty refs_t and then
  2303   * populate it with @SQ line data using refs_from_header(). This is done on
  2304   * cram_open().  Also at start up we can call cram_load_reference() which
  2305   * is used with "scramble -r foo.fa". This replaces the fd->refs with the
  2306   * new one specified. In either case refs2id() is then called which
  2307   * maps ref_entry names to @SQ ids (refs_t->ref_id[]).
  2308   *
  2309   * Later, possibly within a thread, we will want to know the actual ref
  2310   * seq itself, obtained by calling cram_get_ref().  This may use the
  2311   * UR: or M5: fields or the filename specified in the original
  2312   * cram_load_reference() call.
  2313   *
  2314   * Given the potential for multi-threaded reference usage, we have
  2315   * reference counting (sorry for the confusing double use of "ref") to
  2316   * track the number of callers interested in any specific reference.
  2317   */
  2318
  2319  /*
  2320   * Frees/unmaps a reference sequence and associated file handles.
  2321   */
  2322  static void ref_entry_free_seq(ref_entry *e) {
  2323      if (e->mf)
  2324          mfclose(e->mf);
  2325      if (e->seq && !e->mf)
  2326          free(e->seq);
  2327
  2328      e->seq = NULL;
  2329      e->mf = NULL;
  2330  }
  2331
  2332  void refs_free(refs_t *r) {
  2333      RP("refs_free()\n");
  2334
  2335      if (--r->count > 0)
  2336          return;
  2337
  2338      if (!r)
  2339          return;
  2340
  2341      if (r->pool)
  2342          string_pool_destroy(r->pool);
  2343
  2344      if (r->h_meta) {
  2345          khint_t k;
  2346
  2347          for (k = kh_begin(r->h_meta); k != kh_end(r->h_meta); k++) {
  2348              ref_entry *e;
  2349
  2350              if (!kh_exist(r->h_meta, k))
  2351                  continue;
  2352              if (!(e = kh_val(r->h_meta, k)))
  2353                  continue;
  2354              ref_entry_free_seq(e);
  2355              free(e);
  2356          }
  2357
  2358          kh_destroy(refs, r->h_meta);
  2359      }
  2360
  2361      if (r->ref_id)
  2362          free(r->ref_id);
  2363
  2364      if (r->fp)
  2365          bgzf_close(r->fp);
  2366
  2367      pthread_mutex_destroy(&r->lock);
  2368
  2369      free(r);
  2370  }
  2371
  2372  static refs_t *refs_create(void) {
  2373      refs_t *r = calloc(1, sizeof(*r));
  2374
  2375      RP("refs_create()\n");
  2376
  2377      if (!r)
  2378          return NULL;
  2379
  2380      if (!(r->pool = string_pool_create(8192)))
  2381          goto err;
  2382
  2383      r->ref_id = NULL; // see refs2id() to populate.
  2384      r->count = 1;
  2385      r->last = NULL;
  2386      r->last_id = -1;
  2387
  2388      if (!(r->h_meta = kh_init(refs)))
  2389          goto err;
  2390
  2391      pthread_mutex_init(&r->lock, NULL);
  2392
  2393      return r;
  2394
  2395   err:
  2396      refs_free(r);
  2397      return NULL;
  2398  }
