   956      } else if (b[0] < 241) {
   957          b[1] = hgetc(fd->fp);
   958      } else if (b[0] < 249) {
   959          b[1] = hgetc(fd->fp);
   960          b[2] = hgetc(fd->fp);
   961      } else {
   962          int n = b[0]+2, z = 1;
   963          while (n-- >= 249)
   964              b[z++] = hgetc(fd->fp);
   965      }
   966      i = var_get_u64(b, NULL, &v);
   967  #else
   968  //    // Little endian
   969  //    int s = 0;
   970  //    do {
   971  //        b[i++] = c = hgetc(fd->fp);
   972  //        if (c < 0)
   973  //            return -1;
   974  //        v |= (c & 0x7f) << s;
   975  //      s += 7;
   976  //    } while (i < 10 && (c & 0x80));
   977
   978      // Big endian, see also htscodecs/varint.h
   979      do {
   980          b[i++] = c = hgetc(fd->fp);
   981          if (c < 0)
   982              return -1;
