   994  /*
   995   * Decodes a 32-bit little endian value from fd and stores in val.
   996   *
   997   * Returns the number of bytes read on success
   998   *         -1 on failure
   999   */
  1000  static int int32_decode(cram_fd *fd, int32_t *val) {
  1001      int32_t i;
  1002      if (4 != hread(fd->fp, &i, 4))
  1003          return -1;
  1004
  1005      *val = le_int4(i);
  1006      return 4;
  1007  }
