  3099  static void cram_ref_incr_locked(refs_t *r, int id) {
  3100      RP("%d INC REF %d, %d %p\n", gettid(), id,
  3101         (int)(id>=0 && r->ref_id[id]?r->ref_id[id]->count+1:-999),
  3102         id>=0 && r->ref_id[id]?r->ref_id[id]->seq:(char *)1);
  3103
  3104      if (id < 0 || !r->ref_id[id] || !r->ref_id[id]->seq)
  3105          return;
  3106
  3107      if (r->last_id == id)
  3108          r->last_id = -1;
  3109
  3110      ++r->ref_id[id]->count;
  3111  }
