  3119  static void cram_ref_decr_locked(refs_t *r, int id) {
  3120      RP("%d DEC REF %d, %d %p\n", gettid(), id,
  3121         (int)(id>=0 && r->ref_id[id]?r->ref_id[id]->count-1:-999),
  3122         id>=0 && r->ref_id[id]?r->ref_id[id]->seq:(char *)1);
  3123
  3124      if (id < 0 || !r->ref_id[id] || !r->ref_id[id]->seq) {
  3125          return;
  3126      }
  3127
  3128      if (--r->ref_id[id]->count <= 0) {
  3129          assert(r->ref_id[id]->count == 0);
  3130          if (r->last_id >= 0) {
  3131              if (r->ref_id[r->last_id]->count <= 0 &&
  3132                  r->ref_id[r->last_id]->seq) {
  3133                  RP("%d FREE REF %d (%p)\n", gettid(),
  3134                     r->last_id, r->ref_id[r->last_id]->seq);
  3135                  ref_entry_free_seq(r->ref_id[r->last_id]);
  3136                  if (r->ref_id[r->last_id]->is_md5) r->ref_id[r->last_id]->length = 0;
  3137              }
  3138          }
  3139          r->last_id = id;
  3140      }
  3141  }
