  3221  /*
  3222   * Load the entire reference 'id'.
  3223   * This also increments the reference count by 1.
  3224   *
  3225   * Returns ref_entry on success;
  3226   *         NULL on failure
  3227   */
  3228  ref_entry *cram_ref_load(refs_t *r, int id, int is_md5) {
  3229      ref_entry *e = r->ref_id[id];
  3230      int start = 1, end = e->length;
  3230      int start = 1, end = e->length;
  3231      char *seq;
  3232
  3233      if (e->seq) {
  3234          return e;
  3235      }
  3236
  3237      assert(e->count == 0);
  3238
  3239      if (r->last) {
  3240  #ifdef REF_DEBUG
  3241          int idx = 0;
  3242          for (idx = 0; idx < r->nref; idx++)
  3243              if (r->last == r->ref_id[idx])
  3244                  break;
  3245          RP("%d cram_ref_load DECR %d\n", gettid(), idx);
  3246  #endif
  3247          assert(r->last->count > 0);
  3248          if (--r->last->count <= 0) {
  3249              RP("%d FREE REF %d (%p)\n", gettid(), id, r->ref_id[id]->seq);
  3250              if (r->last->seq)
  3251                  ref_entry_free_seq(r->last);
  3252          }
  3253      }
  3254
  3255      if (!r->fn)
  3256          return NULL;
  3257
  3258      /* Open file if it's not already the current open reference */
  3259      if (strcmp(r->fn, e->fn) || r->fp == NULL) {
  3260          if (r->fp)
  3261              if (bgzf_close(r->fp) != 0)
  3262                  return NULL;
  3263          r->fn = e->fn;
  3264          if (!(r->fp = bgzf_open_ref(r->fn, "r", is_md5)))
  3265              return NULL;
  3266      }
  3267
  3268      RP("%d Loading ref %d (%d..%d)\n", gettid(), id, start, end);
  3269
  3270      if (!(seq = load_ref_portion(r->fp, e, start, end))) {
  3271          return NULL;
  3272      }
  3273
  3274      RP("%d Loaded ref %d (%d..%d) = %p\n", gettid(), id, start, end, seq);
  3275
  3276      RP("%d INC REF %d, %"PRId64"\n", gettid(), id, (e->count+1));
  3277      e->seq = seq;
  3278      e->mf = NULL;
  3279      e->count++;
  3280
  3281      /*
  3282       * Also keep track of last used ref so incr/decr loops on the same
  3283       * sequence don't cause load/free loops.
  3284       */
  3285      RP("%d cram_ref_load INCR %d => %"PRId64"\n", gettid(), id, e->count+1);
  3286      r->last = e;
  3287      e->count++;
  3288
  3289      return e;
  3290  }
